//Rajkin Hossain.......
import java.io.*;
import java.util.*;

public class B {
    public static void main(String[] args) throws IOException {
        FI k = new FI(System.in);
        PrintWriter z = new PrintWriter(System.out);

        while (k.hasNext()) {
            int n = k.nextInt();
            String s = k.next();

            int longest = 0;
            int words = 0;
            boolean inside = false;
            int temp = 0;
            boolean started = false;

            for (int i = 0; i < n; i++) {
                char ch = s.charAt(i);

                if (ch == '(') {
                    inside = true;
                    temp = 0;
                    started = false;
                } else if (ch == ')') {
                    inside = false;
                    temp = 0;
                } else {
                    if (!inside) {
                        if (ch == '_') {
                            if (temp > 0) {
                                longest = Math.max(longest, temp);
                                temp = 0;
                            }
                        } else {
                            temp++;
                            if (i == n - 1 || s.charAt(i + 1) == '_') {
                                longest = Math.max(longest, temp);
                                temp = 0;
                            }
                        }
                    } else {
                        if (ch == '_') {
                            started = false;
                        } else {
                            if (!started) {
                                words++;
                                started = true;
                            }
                        }
                    }
                }
            }

            z.println(longest + " " + words);
        }

        z.flush();
    }

    public static class FI {
        BufferedReader br;
        StringTokenizer st;

        public FI(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        public FI(String s) {
            try {
                br = new BufferedReader(new FileReader(s));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        public String next() {
            return nextToken();
        }

        public boolean hasNext() {
            try {
                return br.ready();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return false;
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                String line = null;
                try {
                    line = br.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.valueOf(nextToken());
        }
    }
}
